// The student's own timeline, from today to their master's start (/plan): study stages, English and
// admissions tests, application windows, events, experience and scholarship deadlines. Everything
// is worked out by rules in the browser from the student's answers and the collected data; nothing
// is generated by AI and nothing leaves the browser. Dates from official pages say so; dates from a
// rule of thumb are marked "typical". lib/plan-road.ts lays the items out as the page's
// road; lib/plan-files.ts turns them into the PDF and the calendar file.

import { monthYear } from "@/lib/i18n/format";
import { makeT, type T } from "@/lib/i18n/translate";
import type { LocalName } from "@/lib/local-name";
import { universityKey } from "@/lib/pathway";
import type { PlanAnswers, PlanGoal } from "@/lib/plan-storage";
import type { ChineseName, ResultsProgramme, ResultsUniversity } from "@/lib/results-types";

export type Lane = "study" | "tests" | "applications" | "events" | "experience" | "scholarships";

export const LANES: { id: Lane; label: string }[] = [
  { id: "study", label: "Study" },
  { id: "tests", label: "Tests" },
  { id: "applications", label: "Applications" },
  { id: "events", label: "Events" },
  { id: "experience", label: "Experience" },
  { id: "scholarships", label: "Scholarships" },
];

/** official: the date is on the linked page; typical: worked out by a rule of thumb; yours: from your answers. */
export type Basis = "official" | "typical" | "yours";

/** An official page's own words, shown one tap away ("Aston University’s rule ▾", "MOM’s rule ▾"). */
export type PlanRule = { label: string; quote: string; url: string | null };

/** An answer the plan uses but doesn't have yet; the road asks for it where it is used. */
export type PlanAsk = "graduation" | "status" | "english-test" | "english-date";

export type PlanItem = {
  id: string;
  lane: Lane;
  /** YYYY-MM-DD. A window when `to` is set, otherwise one date. */
  from: string;
  to: string | null;
  /** The full title (PDF and calendar). */
  title: string;
  /** The road's headline: a few words, verb first where it is a task ("Retake IELTS 6.5+"). */
  short: string;
  detail: string;
  basis: Basis;
  url: string | null;
  /** A deadline or the start itself: bold on the chart, a reminder in the calendar. */
  key?: boolean;
  /** More official pages than the one `url` (platforms, employers' careers sites), with a short note each. */
  links?: { label: string; url: string; note?: string }[];
  /** The university it belongs to, in the page's language (applications, starts, events, scholarships). */
  university?: string;
  /** The date that must be met, YYYY-MM-DD (a deadline, an expiry, a usual close, a start): the calendar reminds 14 and 2 days before. */
  due?: string;
  /** Advice that holds for every item of its kind ("apply as soon as it opens…"): said once where they sit together. */
  tip?: string;
  /** Official pages' own words behind a tap: a university's English-test rule, MOM's work rule. */
  rules?: PlanRule[];
  /** The usual application window has passed: check the page this week; `next` is the programme's next intake (month number) if it has closed. */
  late?: { next: number | null; note: string };
  /** The answer this item needs (a short prompt in its place). */
  ask?: PlanAsk;
  /** Scholarship items: the application they go with, the Kaplan degree's (diploma students) or the master's. */
  for?: "degree" | "masters";
  /** A programme's English name, shown under its name in the page's language (applications use it); `translated`: that name is our translation. */
  en?: { name: string; translated: boolean };
  /** The headline is the page's own words, kept in English (an event's title). */
  lang?: "en";
};

export type PlanEvent = {
  id: string;
  university: string;
  kind: "scholarship" | "deadline" | "event" | "fee-reduction" | "application-fee-waiver" | "applications-open" | "application-deadline";
  title: string;
  value: string | null;
  date: string | null;
  url: string;
};
/** `link`: a platform's label in the plan's list, its note folded in ("Forage (free, self-paced)"). */
export type PlanActivity = { id: string; kind: string; mode: string; title: string; short: string; universities: string[]; applyFrom: string | null; applyBy: string | null; start: string | null; end: string | null; note: string | null; link?: string | null; url: string };
/** A scholarship or fee reduction the student could apply for, from a university's page or Kaplan's. */
export type PlanScholarship = {
  id: string;
  university: string;
  title: string;
  value: string | null;
  /** The amount or percentage the page states, when it was read as a number (data/raw/benefits.json). */
  amount?: number | null;
  percent?: number | null;
  /** YYYY-MM-DD as the page states it; it may be another round's. */
  deadline: string | null;
  /** The intake the page ties the award (and its deadline) to, as worded there ("January 2027"). */
  intake?: string | null;
  /** Considered with the programme application, no separate form. */
  automatic: boolean | null;
  /** What to get ready, in the source's own terms. */
  prepare: string[];
  /** Who it is for, in the page's words (used to tell awards for the university's own graduates). */
  eligibility?: string | null;
  /** The programmes or faculties it is limited to, as the page words it ("Faculty of Medicine"). */
  disciplines?: string | null;
  url: string | null;
  /** "kaplan": for Kaplan students (a partner university's award at Kaplan, or Kaplan's own). */
  source: "university" | "kaplan";
  /** Kaplan awards: "bachelor" is for the degree after a Kaplan diploma; "both" also for a Kaplan master's. */
  stage?: "bachelor" | "both";
};
/**
 * A scholarship as the plan shows it. upcoming: the page's date is the student's round; last-round: the
 * page's date is another round's, and `due` is the student's round worked out from it; closed: the round
 * for the student's start has passed (kept for next year's reference); undated; automatic.
 */
export type PlanScholarshipCard = PlanScholarship & {
  status: "upcoming" | "last-round" | "closed" | "undated" | "automatic";
  when: string;
  /** The student's round, YYYY-MM-DD: as the page states it (official) or worked out from another round's (typical). */
  due: string | null;
  dueBasis: "official" | "typical" | null;
  /** The page's own date when `due` is worked out from it ("Last round: 12 Apr 2026"). */
  note: string | null;
  /** A rough size, only to order a university's awards: fully funded first, then sums as stated, percentages of the programme's fee. */
  worth: number;
  /** The plan item carrying its window (`sch-…`), when it has one. */
  item: string | null;
  /** The university's name in the page's language (`university` stays the English name). */
  school: string;
  /** The application it goes with: the Kaplan degree's (diploma students) or the master's. */
  for: "degree" | "masters";
  /** Ids of the duplicates merged into this one (the same award listed twice on the pages). */
  merged: string[];
  /** The other official pages that list it (a merged duplicate's), besides `url`. */
  also: string[];
};
export type DegreeStage = { name: string; university: string; start: number; end: number; estimate: boolean } | null;

export type PlanInput = {
  today: string;
  answers: PlanAnswers;
  programmes: { p: ResultsProgramme; u: ResultsUniversity }[];
  /** Diploma students: the planned Kaplan degree with estimated start and end (month numbers, year*12+month-1). */
  degree: DegreeStage;
  /** The university awarding the student's bachelor's (the Kaplan degree's partner): its activities, scholarships and alumni awards. */
  partner: string | null;
  events: PlanEvent[];
  scholarships: PlanScholarship[];
  activities: PlanActivity[];
  mom: { url: string; quotes: string[] };
  /** The student's school is outside MOM's list of institutions whose students may work in vacations. */
  notExempt: boolean;
  /** How recent an English test must be, quoted from universities' own pages. */
  englishRules: { university: string; quote: string; url: string }[];
  /** Employers hiring in the student's field in Singapore (careers data), with internships flagged. */
  employers: { name: string; url: string; intern: boolean }[];
  /** The page's language: every title, detail and note is written in it (English when left out). */
  t?: T;
  locale?: string;
  /** A university's or programme's name in the page's language, with the English one beside it there (components/results/names.ts); matching keeps the English names. */
  name?: (en: string, zh: ChineseName | null) => LocalName;
  /** A university known only by its English name (events, English rules) in the page's language (lib/site-names.ts). */
  school?: (en: string) => string;
  /** A Kaplan degree's name in the page's language (lib/site-names.ts). */
  degreeName?: (en: string) => string;
};

export type Plan = {
  /** The first shortlisted start (month number). */
  start: number;
  /** The last shortlisted start: the plan, the chart and the PDF run to here. */
  end: number;
  from: number;
  items: PlanItem[];
  notes: string[];
  scholarships: PlanScholarshipCard[];
  /** The work rule that applies to the student's pass: one line for Now, the longer rule, and MOM's words. */
  work: { line: string; detail: string; rule: PlanRule | null } | null;
  /** Answers the plan would use but doesn't have. */
  asks: PlanAsk[];
};

/** "Sep 2027", in the given language. */
export const monthLabel = (t: number, locale = "en-SG") => monthYear(locale, t);
export const monthOf = (iso: string) => Number(iso.slice(0, 4)) * 12 + Number(iso.slice(5, 7)) - 1;
const iso = (t: number, day = 1) => `${Math.floor(t / 12)}-${String((t % 12) + 1).padStart(2, "0")}-${String(day).padStart(2, "0")}`;
const lastDay = (t: number) => new Date(Math.floor(t / 12), (t % 12) + 1, 0).getDate();
/** The last day of a month. */
const endOf = (t: number) => iso(t, lastDay(t));
/** The same day `n` months on (or back), kept inside the month ("31 Aug" + 1 = "30 Sep"). */
export const addMonths = (d: string, n: number) => {
  const t = monthOf(d) + n;
  return iso(t, Math.min(Number(d.slice(8, 10)), lastDay(t)));
};

/** The first intake month at or after `after` (a 12-bit mask; September when the page names none). */
function nextStart(mask: number, after: number): { t: number; stated: boolean } {
  const m = mask || 1 << 8;
  for (let t = after; t < after + 36; t++) if (m & (1 << (t % 12))) return { t, stated: !!mask };
  return { t: after, stated: false };
}

const WORDS = (s: string) =>
  s
    .toLowerCase()
    .replace(/&/g, " and ")
    .replace(/\((single|double)[^)]*\)|\b(honours|hons|top-up|with)\b/g, " ")
    .split(/[^a-z]+/)
    .filter((w) => w && !["and", "of", "in", "the", "bachelor", "programmes", "programme", "preview", "session", "talk"].includes(w))
    .map((w) => w.replace(/s$/, ""));

/** A degree name as its type ("Bachelor of Science (Honours)" → "science") and the majors it names. */
function degreeParts(name: string): { head: string; majors: string[][] } {
  const rest = name.replace(/^.*?bachelor of\s+/i, "").replace(/\((single|double)[^)]*\)/gi, "");
  const inAt = rest.search(/\bin\b/i);
  const paren = rest.indexOf("(");
  const cut = inAt >= 0 ? inAt : paren >= 0 ? paren : rest.length;
  const head = WORDS(rest.slice(0, cut).replace(/\/.*$/, "")).join(" ");
  const majors = rest
    .slice(inAt >= 0 ? inAt + 2 : cut)
    .split(/\/|,/)
    .map(WORDS)
    .filter((w) => w.length);
  return { head, majors };
}

/**
 * Whether one of Kaplan's previews ("Murdoch University – Bachelor of Business in Accounting (Single/Double
 * Major)") is about the student's planned degree ("Bachelor of Business in Accounting"). A preview that
 * names majors fits when one of them is the degree's major; one that names only a degree type ("Bachelor of
 * Arts (Honours) Programmes", "IT Programmes") fits degrees of that type. Master's previews never fit.
 */
export function previewFits(title: string, degree: string): boolean {
  if (/master|graduate certificate|postgraduate/i.test(title)) return false;
  if (!/bachelor of/i.test(title)) return /\bIT\b/.test(title) && /information technology|comput|cyber|forensic|software/i.test(degree);
  const p = degreeParts(title);
  const mine = degreeParts(degree);
  const own = mine.majors.flat();
  // "Cyber Forensic & Security/ Business Information Systems/ Computer Science": each major on its own.
  // A preview major may add one word to the degree's ("Banking & Finance" for Finance), not more
  // ("Hospitality & Tourism Management" is not Management).
  if (p.majors.length) return own.length > 0 && p.majors.some((w) => w.every((x) => own.includes(x)) || (own.every((x) => w.includes(x)) && w.length - own.length <= 1));
  // Only a type: "Bachelor of Arts (Honours) Programmes", "Bachelor of Laws (Honours) (Top-up)".
  return !!p.head && p.head === mine.head;
}

/** Words a scholarship's field limit uses for each programme field (lib/topups.ts FIELD_RULES ids). */
const FIELD_WORDS: Record<string, RegExp> = {
  business: /business|management|commerce|econom/i,
  "accounting-finance": /business|financ|account|econom|commerce|management/i,
  marketing: /business|marketing|management/i,
  it: /comput|information technology|engineering|digital|data|artificial intelligence/i,
  "ai-data": /comput|data|artificial intelligence|machine learning|engineering|mathemat/i,
  communication: /communication|media|journalism|arts|humanities|social science/i,
  "psychology-counselling": /psycholog|counsel|social science|health/i,
  "law-criminology": /\blaw\b|justice|crimin|social science/i,
  "hospitality-tourism": /hospitality|tourism|events|business|management/i,
  education: /education/i,
  "healthcare-nursing": /health|nursing|medicine|medical/i,
  construction: /construction|built environment|architecture|building|engineering/i,
  "sports-science": /sport|exercise|health/i,
};

/** Whether a scholarship limited to some fields ("Faculty of Medicine") can apply to one of these programmes. */
function forFields(limit: string | null | undefined, programmes: { name: string; discipline: string }[]): boolean {
  if (!limit?.trim() || /\b(any|all)\b (subject|discipline|programme|course|taught)|^any\b|most postgraduate|eligible (full-time|programmes|bachelor|one-year|graduate|masters)/i.test(limit)) return true;
  const words = (p: { name: string; discipline: string }) => FIELD_WORDS[p.discipline] ?? /$^/;
  const named = (p: { name: string }) => limit.toLowerCase().includes(p.name.toLowerCase().replace(/^(msc|ma|mba|master of [a-z]+ in|master of)\s+/i, ""));
  // "MBA" (an award on an MBA's own page, lib/plan-data.ts) is for MBA programmes only.
  const mba = (p: { name: string }, text: string) => /\bmba\b/i.test(text) && /\bMBA\b|business administration/i.test(p.name);
  // "All except Southampton Business School programmes": out only for those fields.
  if (/except|exclu/i.test(limit)) {
    const [, excluded = ""] = limit.split(/except|exclu\w*/i);
    return programmes.some((p) => !words(p).test(excluded) && !named(p) && !mba(p, excluded));
  }
  return programmes.some((p) => words(p).test(limit) || named(p) || mba(p, limit));
}

const FULL = ["january", "february", "march", "april", "may", "june", "july", "august", "september", "october", "november", "december"];
/** Every "Month YYYY" an intake text names ("September 2026 or January 2027"), as month numbers. */
const intakesIn = (s: string) => [...s.matchAll(/(january|february|march|april|may|june|july|august|september|october|november|december)\s+(20\d\d)/gi)].map((m) => Number(m[2]) * 12 + FULL.indexOf(m[1].toLowerCase()));

/**
 * Awards for the university's own graduates (alumni discounts). The pages don't mark them, so they are
 * told from the wording: "alumni" in the title, or eligibility for those who graduated from or studied
 * at the university before.
 */
const ALUMNI_TITLE = /\balumni\b/i;
const ALUMNI_WHO = /\ball alumni\b|\bformer students? of\b|\b(graduates?|alumni) of the university\b|\bgraduated (with [^.]{0,80})?from the university\b|\bpreviously (studied|matriculated)\b/i;
export const alumniOnly = (s: Pick<PlanScholarship, "title" | "eligibility">) => ALUMNI_TITLE.test(s.title) || ALUMNI_WHO.test(s.eligibility ?? "");
/**
 * Awards for alumni of a network's members ("UCD offers alumni of Universitas 21 partner universities a
 * tuition fee scholarship"): for graduates of the other members, not of the awarding university. None of
 * Kaplan's partner universities is another member (UCD awards it), so no student here is shown one.
 */
const NETWORK = /\buniversitas 21\b|\bU21\b/i;
const networkAlumni = (s: Pick<PlanScholarship, "title" | "eligibility">) => alumniOnly(s) && NETWORK.test(`${s.title} ${s.eligibility ?? ""}`);

/** A title as one key for spotting the same award listed twice ("International Student Scholarship (ISS)" = "International Student Scholarships"). */
const awardKey = (s: PlanScholarship) =>
  `${universityKey(s.university)}|${s.title
    .toLowerCase()
    .replace(/\([^)]*\)/g, " ")
    .replace(/\s*[-–—]\s*[£$€][\d,.]+\s*$/, "")
    .split(/[^a-z0-9]+/)
    .filter(Boolean)
    .map((w) => w.replace(/s$/, ""))
    .join(" ")}`;

/**
 * The same award listed under two titles on two pages (Birmingham City University's Singapore page and
 * its scholarships page): the same value, and one page's words on who it is for inside the other's, or
 * the same first sentence.
 */
function sameAward(p: PlanScholarship, q: PlanScholarship): boolean {
  const flat = (s: string | null | undefined) =>
    (s ?? "")
      .toLowerCase()
      .replace(/[‘’]/g, "'")
      .replace(/\s+/g, " ")
      .replace(/[.\s]+$/, "")
      .trim();
  if (universityKey(p.university) !== universityKey(q.university) || !flat(p.value) || flat(p.value) !== flat(q.value)) return false;
  const [a, b] = [flat(p.eligibility), flat(q.eligibility)];
  if (a.length < 30 || b.length < 30) return false;
  const first = (s: string) => s.split(/(?<=\.) /)[0];
  return a.includes(b) || b.includes(a) || first(a) === first(b);
}

/** A page's site: the university's own domain ("nus.edu.sg") and the part before it ("mscstrategy"; "" for the main site). */
function siteOf(url: string | null): { root: string; sub: string } | null {
  let host: string;
  try {
    host = new URL(url ?? "").hostname.toLowerCase().replace(/^www\./, "");
  } catch {
    return null;
  }
  const labels = host.split(".");
  // "nus.edu.sg", "sheffield.ac.uk", "um.edu.mo"; "hku.hk", "hksyu.edu".
  const n = labels.length >= 3 && labels.at(-1)!.length === 2 && /^(ac|edu|com|org|gov|net|co)$/.test(labels.at(-2)!) ? 3 : 2;
  return { root: labels.slice(-n).join("."), sub: labels.slice(0, -n).join(".") };
}
/** A university's graduate admissions office or graduate school, whose dates are for all its programmes. */
const ADMISSIONS_SITE = /^(admissions?|gs|grs|fytgs|graduate|pg)$/;

/** Display fixes for a page's award title: ALL CAPS in title case (short words like STEM kept), and a trailing " - £5,000" the value repeats. */
function tidyTitle(title: string, value: string | null): string {
  let s = title.trim();
  if (s === s.toUpperCase() && /[A-Z]{5}/.test(s))
    s = s
      .split(/\s+/)
      .map((w, i) => (i > 0 && /^(IN|OF|AND|FOR|THE|TO|AT|ON)$/.test(w) ? w.toLowerCase() : w.length <= 4 ? w : w[0] + w.slice(1).toLowerCase()))
      .join(" ");
  const tail = /\s*[-–—]\s*([£$€][\d,.]+)\s*$/.exec(s);
  if (tail && value?.replace(/\s/g, "").includes(tail[1])) s = s.slice(0, tail.index).trim();
  return s;
}

/** Lines in "What to prepare" that only say the page has nothing to prepare. */
const EMPTY_LINE = /does not state|no application steps|not (stated|listed|specified)\b|nothing to prepare|check the university's page for how to apply/i;

/** Whether a "What to prepare" line only repeats the page's own round (its deadline or intake), which the card's date line already says. */
function repeatsRound(line: string, s: PlanScholarship): boolean {
  const named: RegExp[] = [];
  if (s.deadline) {
    const [y, m, d] = s.deadline.split("-").map(Number);
    named.push(new RegExp(`\\b${d}(st|nd|rd|th)?\\s+${FULL[m - 1].slice(0, 3)}[a-z]*,?\\s+${y}\\b`, "i"));
  }
  for (const m of intakesIn(s.intake ?? "")) named.push(new RegExp(`\\b${FULL[m % 12]}\\s+${Math.floor(m / 12)}\\b`, "i"));
  return named.some((re) => re.test(line));
}

/** The largest sum ("£5,000", "S$10,000 / S$7,500") and percentage ("10-35%") an award's value names. */
function sizeOf(s: PlanScholarship): { amount: number | null; percent: number | null; full: boolean } {
  const text = `${s.title} ${s.value ?? ""}`;
  const sums = [...(s.value ?? "").matchAll(/(?:[£€$]|\b(?:GBP|EUR|AUD|SGD|HKD|USD|NZD|CAD)\s?)\s?(\d[\d,]*(?:\.\d+)?)/gi)].map((m) => Number(m[1].replace(/,/g, "")));
  const pcts = [...(s.value ?? "").matchAll(/(\d{1,3})\s?%/g)].map((m) => Number(m[1]));
  const amount = Math.max(s.amount ?? 0, ...sums) || null;
  const percent = Math.max(s.percent ?? 0, ...pcts) || null;
  return { amount, percent, full: /fully[- ]funded|full (tuition|fee)/i.test(text) || (percent ?? 0) >= 100 };
}

const GOAL_LANE: Record<PlanGoal["lever"], Lane> = { grade: "study", ielts: "tests", internship: "experience", work: "experience", research: "experience", later: "study" };

/**
 * A goal's words: its headline ("Reach IELTS 7 by Mar 2028") and, once the date it was set for has
 * passed, a line saying it is due now (empty otherwise).
 */
export function goalWords(g: PlanGoal, today: string, t: T, locale: string): { head: string; rule: string; by: string } {
  const by = g.by < today ? today : g.by;
  const date = monthYear(locale, monthOf(by));
  const score = g.target ?? 0;
  const head =
    g.lever === "grade"
      ? g.unit === "wam"
        ? t("Reach WAM {score} by {date}", { score, date })
        : g.unit === "mark"
          ? t("Reach an average mark of {score}% by {date}", { score, date })
          : g.unit === "gpa"
            ? t("Reach GPA {score}/{scale} by {date}", { score, scale: g.scale ?? 4, date })
            : g.unit === "class"
              ? score >= 70
                ? t("Reach a First by {date}", { date })
                : score >= 60
                  ? t("Reach a 2:1 by {date}", { date })
                  : t("Reach a 2:2 by {date}", { date })
              : t("Reach UK mark {score} by {date}", { score, date })
      : g.lever === "ielts"
        ? t("Reach IELTS {score} by {date}", { score, date })
        : g.lever === "internship"
          ? t("Do one more internship in your field by {date}", { date })
          : g.lever === "work"
            ? t(score === 1 ? "Have 1 year of full-time work by {date}" : "Have {n} years of full-time work by {date}", { n: score, date })
            : g.lever === "research"
              ? t("Add one research output by {date}", { date })
              : t("Start in {date}, after a year of full-time work", { date });
  const set = monthYear(locale, monthOf(g.by));
  const rule = g.by < today ? t("The date set for it ({date}) has passed, so the goal is due now.", { date: set }) : "";
  return { head, rule, by };
}

/** A goal from Where you stand as the student's own item: from today to the date it was set for. */
function goalItem(g: PlanGoal, today: string, t: T, locale: string): PlanItem {
  const { head, rule, by } = goalWords(g, today, t, locale);
  return { id: `goal-${g.lever}-${g.id}`, lane: GOAL_LANE[g.lever], from: today, to: by > today ? by : null, title: head, short: head, detail: rule, basis: "yours", url: null, due: by };
}

export function buildPlan(x: PlanInput): Plan {
  const t = x.t ?? makeT({});
  const locale = x.locale ?? "en-SG";
  const local = x.name ?? ((en: string): LocalName => ({ name: en, en: null, translated: false }));
  const name = (en: string, zh: ChineseName | null) => local(en, zh).name;
  const school = x.school ?? ((en: string) => en);
  const degreeName = x.degreeName ?? ((en: string) => en);
  const monthLabel = (m: number) => monthYear(locale, m);
  const a = x.answers;
  const now = monthOf(x.today);
  const items: PlanItem[] = [];
  const notes: string[] = [];
  const asks: PlanAsk[] = [];
  /** A month as its first day, or today when that month has already begun. */
  const at = (t: number) => (t <= now ? x.today : iso(t));

  // When the bachelor's ends: the planned Kaplan degree for diploma students, else the graduation date.
  const grad = a.graduationYear && a.graduationMonth ? a.graduationYear * 12 + a.graduationMonth - 1 : null;
  if (grad == null) asks.push("graduation");
  if (!a.status) asks.push("status");
  const degreeEnd = x.degree ? x.degree.end : grad ?? now + 6;
  if (a.level === "diploma" && grad != null && grad >= now) {
    items.push({ id: "diploma", lane: "study", from: x.today, to: endOf(grad), title: t("Diploma"), short: t("Finish your diploma"), detail: "", basis: "yours", url: null });
  }
  if (x.degree && x.degree.end >= now) {
    const university = school(x.degree.university);
    items.push({
      id: "degree",
      lane: "study",
      from: at(x.degree.start),
      to: endOf(x.degree.end),
      title: t("Your degree"),
      short: x.degree.start <= now ? t("Finish your degree") : t("Start your degree at {university}", { university }),
      detail: t("{degree} at {university}.", { degree: degreeName(x.degree.name), university }),
      basis: x.degree.estimate ? "typical" : "yours",
      url: null,
      university,
    });
  } else if (!x.degree && a.level === "degree" && grad != null && grad >= now) {
    items.push({ id: "degree", lane: "study", from: x.today, to: endOf(grad), title: t("Your degree"), short: t("Finish your degree"), detail: "", basis: "yours", url: null });
  }

  // Each shortlisted programme: its first intake after the degree (and after this month), and an
  // application window opening about 12 months before and closing about 6 months before (rule of
  // thumb: September starts open the previous Sep–Oct). When that window has already closed, the
  // item says so ("late") and names the next intake, rather than moving to it unasked.
  const after = Math.max(degreeEnd + 1, now + 1);
  const starts = x.programmes.map(({ p, u }) => ({ p, u, ...nextStart(p.intake, after) }));
  const start = starts.length ? Math.min(...starts.map((s) => s.t)) : after + 2;
  const end = starts.length ? Math.max(...starts.map((s) => s.t)) : start;
  for (const s of starts) {
    const opens = s.t - 12;
    const closes = s.t - 6;
    const late = closes < now;
    const university = name(s.u.name, s.u.zh);
    const own = local(s.p.name, s.p.zh);
    const programme = own.name;
    const en = own.en ? { name: own.en, translated: own.translated } : undefined;
    const next = late && s.stated ? nextStart(s.p.intake, s.t + 1).t : null;
    const to = late ? endOf(s.t - 1) : endOf(closes);
    items.push({
      id: `apply-${s.p.id}`,
      lane: "applications",
      from: at(opens),
      to,
      title: t("Apply: {programme} · {university}", { programme, university }),
      short: `${programme} · ${university}`,
      detail: "",
      // A late window's own lines say what to do (lib/plan-road.ts).
      tip: late
        ? undefined
        : opens > now
          ? t("Apply then: universities give conditional offers before every condition is met.")
          : t("Apply now: universities give conditional offers before every condition is met."),
      basis: "typical",
      url: s.p.url,
      university,
      en,
      due: to,
      late: late
        ? { next, note: next != null ? t("If it has closed, the next intake is {date}.", { date: monthYear(locale, next, "long") }) : t("If it has closed, check the page for the next intake.") }
        : undefined,
    });
    items.push({
      id: `start-${s.p.id}`,
      lane: "study",
      from: iso(s.t),
      to: null,
      title: t("Start: {programme} · {university}", { programme, university }),
      short: `${programme} · ${university}`,
      detail: "",
      basis: s.stated ? "official" : "typical",
      url: s.p.url,
      key: true,
      university,
      en,
      due: iso(s.t),
    });
  }
  if (starts.length) {
    const first = Math.min(...starts.map((s) => s.t - 12));
    items.push({
      id: "documents",
      lane: "applications",
      from: at(first - 2),
      to: endOf(Math.max(now + 1, first)),
      title: t("Get your documents ready"),
      short: t("Get documents ready"),
      detail: t("Transcripts so far, two references (ask early), a personal statement for each programme and a CV."),
      basis: "typical",
      url: null,
    });
    // Offers come in the months before the first start (never earlier than today), and this runs to the
    // last start on the shortlist, since a later start's offer can come after the first's.
    items.push({
      id: "visa",
      lane: "applications",
      from: at(start - 4),
      to: endOf(end - 1),
      title: t("Accept an offer, then visa and housing"),
      short: t("Accept an offer, then visa and housing"),
      detail: t("Meet the offer’s conditions, pay the deposit, apply for the student visa and book housing."),
      basis: "typical",
      url: null,
    });
  }

  // Tests: the highest IELTS any shortlisted programme asks for, against the student's own score and
  // its date. IELTS recommends results be treated as valid for two years from the test date, and
  // universities check that at application or at the start of the course, so a result must last
  // until the latest start on the shortlist: a new test is taken no earlier than 23 months before it.
  const needIelts = Math.max(0, ...x.programmes.map(({ p }) => p.ielts ?? 0));
  const firstOpen = starts.length ? Math.max(now, Math.min(...starts.map((s) => s.t - 12))) : start - 12;
  const lastStart = end;
  // A shortlisted university's own wording, when we have it, shows the rule the student is held to:
  // kept as published, one tap away.
  const rule = x.englishRules.find((r) => starts.some((s) => s.u.name === r.university));
  const rules = rule ? [{ label: t("{university}’s rule", { university: school(rule.university) }), quote: rule.quote, url: rule.url }] : undefined;
  const IELTS_URL = rule?.url ?? "https://ielts.org/organisations/ielts-for-organisations/verifying-ielts-results";
  if (needIelts) {
    if (!a.englishTest) asks.push("english-test");
    const has = a.englishTest === "ielts" && a.englishScore != null;
    const taken = has && a.englishTestYear && a.englishTestMonth ? a.englishTestYear * 12 + a.englishTestMonth - 1 : null;
    if (has && taken == null) asks.push("english-date");
    const expires = taken != null ? taken + 24 : null;
    const earliest = Math.max(now, lastStart - 23);
    // Before applications open; once they are open, while they still are (to the end of the apply window).
    const applyEnd = start - 6;
    const latest = firstOpen - 1 >= earliest ? firstOpen - 1 : Math.max(earliest, applyEnd);
    const window = (title: string, short: string, why: string): PlanItem => ({
      id: "ielts",
      lane: "tests",
      from: at(earliest),
      to: endOf(latest),
      title,
      short,
      detail: why,
      basis: "typical",
      url: IELTS_URL,
      rules,
    });
    if (!has || a.englishScore! < needIelts) {
      items.push(
        window(
          t("English test: IELTS {score}", { score: needIelts }),
          t("Take IELTS {score}+", { score: needIelts }),
          has ? t("You have {mine}; you need {score}.", { mine: a.englishScore!, score: needIelts }) : t("Your shortlist asks for up to IELTS {score} (or an equivalent test).", { score: needIelts }),
        ),
      );
    } else if (expires != null && expires <= now) {
      items.push(window(t("Retake IELTS ({score}+)", { score: needIelts }), t("Retake IELTS {score}+", { score: needIelts }), t("Your {score} is already over 2 years old.", { score: a.englishScore! })));
    } else if (expires != null && expires <= lastStart) {
      items.push({
        id: "ielts-expires",
        lane: "tests",
        from: iso(expires),
        to: null,
        title: t("Your IELTS {score} expires", { score: a.englishScore! }),
        short: t("Your {score} expires {date}", { score: a.englishScore!, date: monthLabel(expires) }),
        detail: t("Taken {taken}, so 2 years old by {expires}, before your {start} start.", { taken: monthLabel(taken!), expires: monthLabel(expires), start: monthLabel(lastStart) }),
        basis: "yours",
        url: IELTS_URL,
        key: true,
        due: iso(expires),
        rules,
      });
      items.push(window(t("Retake IELTS ({score}+)", { score: needIelts }), t("Retake IELTS {score}+", { score: needIelts }), ""));
    } else if (expires != null) {
      items.push({
        id: "ielts",
        lane: "tests",
        from: x.today,
        to: endOf(expires - 1),
        title: t("IELTS {score}: valid to {date}", { score: a.englishScore!, date: monthLabel(expires) }),
        short: t("IELTS {score}: valid to {date}", { score: a.englishScore!, date: monthLabel(expires) }),
        detail: t("Enough for all your programmes (up to {need}) and under 2 years old at your {start} start.", { need: needIelts, start: monthLabel(lastStart) }),
        basis: "yours",
        url: IELTS_URL,
        rules,
      });
    } else {
      items.push({
        id: "ielts",
        lane: "tests",
        from: x.today,
        to: null,
        title: t("IELTS {score}: check its date", { score: a.englishScore! }),
        short: t("Check your IELTS {score} is recent enough", { score: a.englishScore! }),
        detail: t("Meets your shortlist (up to {need}). Taken before {date}? Then it will be over 2 years old at your start: add the test month to check.", {
          need: needIelts,
          date: monthLabel(lastStart - 24),
        }),
        basis: "yours",
        url: IELTS_URL,
        rules,
        ask: "english-date",
      });
    }
  }
  for (const test of ["gre", "gmat"] as const) {
    const req = x.programmes.filter(({ p }) => p[test]?.status === "required");
    if (!req.length || a[test] != null) continue;
    items.push({
      id: test,
      lane: "tests",
      from: at(firstOpen - 4),
      to: endOf(Math.max(now, firstOpen - 1)),
      title: t("Prepare and sit the {test}", { test: test.toUpperCase() }),
      short: t("Prepare and sit the {test}", { test: test.toUpperCase() }),
      detail: t("Needed for {list}.", { list: req.map(({ p }) => name(p.name, p.zh)).join(", ") }),
      basis: "typical",
      url: null,
    });
  }

  // Events, deadlines and scholarships from the universities' own pages, still ahead and before the
  // last start.
  const last = iso(end, 28);
  // An application date names its intake ("January 2027 Postgraduate Programmes"): keep it only when
  // that is when one of the student's programmes at that university starts.
  // A date given for one programme ("Master of Social Work") counts only when that programme is on the
  // shortlist; research degrees are never the student's plan.
  const squash = (s: string) => s.toLowerCase().replace(/[^a-z0-9]+/g, " ").trim();
  const names = new Set(x.programmes.map(({ p, u }) => `${u.name}|${squash(p.name)}`));
  // An application date from a programme's or a faculty's own site (mscstrategy.nus.edu.sg,
  // www.comp.nus.edu.sg) is for the programmes on that site; one from the university's main site or its
  // graduate admissions office is for all of them.
  const forShortlist = (e: PlanEvent) => {
    const page = siteOf(e.url);
    if (!page || !page.sub || ADMISSIONS_SITE.test(page.sub)) return true;
    return starts.some(({ p, u }) => {
      const own = siteOf(p.url);
      return u.name === e.university && !!own?.sub && own.root === page.root && (own.sub === page.sub || own.sub.endsWith(`.${page.sub}`) || page.sub.endsWith(`.${own.sub}`));
    });
  };
  const isApplication = (e: PlanEvent): e is PlanEvent & { kind: "applications-open" | "application-deadline" } => e.kind === "applications-open" || e.kind === "application-deadline";
  /** Whether a page's heading already says what the date is ("Applications close for February 2027 entry"). */
  const saysKind = (e: PlanEvent) => (e.kind === "applications-open" ? /\bopen(s|ing)?\b/i : /\b(deadline|close[sd]?|closing)\b/i).test(e.title);
  // The same date on the same page under two headings ("Application deadline for all applicants", "Key
  // Dates") is one row, under the heading that says what it is.
  const dated = new Map<string, PlanEvent>();
  for (const e of x.events) {
    if (!e.date || e.date < x.today || e.date > last) continue;
    if (/\b(PhD|MPhil|Doctor|doctoral|research postgraduate)\b/i.test(e.title)) continue;
    if (/^(Master|MSc|MA|MBA|MSSc|MPhil|Postgraduate (Diploma|Certificate))\b/.test(e.title) && !names.has(`${e.university}|${squash(e.title)}`)) continue;
    if (isApplication(e)) {
      const intake = intakesIn(`${e.title} ${e.value ?? ""}`)[0];
      if (intake != null && !starts.some((s) => s.u.name === e.university && s.t === intake)) continue;
      if (!forShortlist(e)) continue;
    }
    const k = isApplication(e) ? `${e.university}|${e.kind}|${e.date}|${e.url}` : e.id;
    const had = dated.get(k);
    if (!had || (isApplication(e) && saysKind(e) && !saysKind(had))) dated.set(k, e);
  }
  for (const e of dated.values()) {
    const lane: Lane = e.kind === "event" ? "events" : e.kind === "deadline" || isApplication(e) ? "applications" : "scholarships";
    // An application date is headed by what it is; the page's own heading ("Key Dates") goes in the detail.
    const kind = isApplication(e) && !saysKind(e) ? (e.kind === "applications-open" ? t("Applications open") : t("Application deadline")) : null;
    const key = e.kind !== "event" && e.kind !== "scholarship";
    items.push({
      id: `ev-${e.id}`,
      lane,
      from: e.date!,
      to: null,
      title: kind ? `${kind}: ${e.title}` : e.title,
      short: kind ?? e.title,
      detail: `${school(e.university)}${kind ? ` · ${e.title}` : ""}${e.value ? ` · ${e.value}` : ""}.`,
      basis: "official",
      url: e.url,
      key,
      university: school(e.university),
      due: key && e.kind !== "applications-open" ? e.date! : undefined,
      lang: kind ? undefined : "en",
    });
  }

  // Scholarships: the shortlisted universities' own, and Kaplan's for Kaplan students. Awards for a
  // university's own graduates only for that university's graduates; the same award listed twice
  // (as a scholarship and a fee reduction, or on two pages) once.
  const shortUnis = new Set(x.programmes.map(({ u }) => u.name));
  const kaplanMasters = x.programmes.some(({ p }) => p.kaplan);
  const ownGraduate = (university: string) => !!x.partner && universityKey(x.partner) === universityKey(university);
  const eligible = x.scholarships.filter(
    (s) =>
      !networkAlumni(s) &&
      (!alumniOnly(s) || ownGraduate(s.university)) &&
      (s.source === "university"
        ? shortUnis.has(s.university) &&
          forFields(
            s.disciplines,
            x.programmes.filter(({ u }) => u.name === s.university).map(({ p }) => ({ name: p.name, discipline: p.discipline })),
          )
        : s.stage === "bachelor"
          ? a.level === "diploma" && !!x.degree && s.university === x.partner
          : (a.level === "diploma" && !!x.degree) || kaplanMasters),
  );
  // The fuller listing of a duplicate is kept (a value, a date, more to prepare), with the other's page
  // as a second link; when either page says it is automatic, it is.
  type Listing = { s: PlanScholarship; merged: string[]; also: string[] };
  const fullness = (s: PlanScholarship) => (s.value ? 4 : 0) + (s.deadline ? 2 : 0) + s.prepare.length / 10;
  const join = (p: Listing, q: Listing): Listing => {
    const [keep, drop] = fullness(q.s) > fullness(p.s) ? [q, p] : [p, q];
    return {
      s: { ...keep.s, prepare: keep.s.prepare.length ? keep.s.prepare : drop.s.prepare, automatic: keep.s.automatic || drop.s.automatic ? true : keep.s.automatic },
      merged: [...keep.merged, ...drop.merged, drop.s.id],
      also: [...new Set([...keep.also, ...drop.also, ...(drop.s.url ? [drop.s.url] : [])])].filter((u) => u !== keep.s.url),
    };
  };
  const byKey = new Map<string, Listing>();
  for (const s of eligible) {
    const k = awardKey(s);
    const had = byKey.get(k);
    byKey.set(k, had ? join(had, { s, merged: [], also: [] }) : { s, merged: [], also: [] });
  }
  // Then the same award under two titles (sameAward).
  const listings: Listing[] = [];
  for (const l of byKey.values()) {
    const twin = listings.findIndex((m) => sameAward(m.s, l.s));
    if (twin < 0) listings.push(l);
    else listings[twin] = join(listings[twin], l);
  }
  // A Kaplan award goes with the Kaplan degree's application for a diploma student, else with the master's.
  const forOf = (s: PlanScholarship): "degree" | "masters" => (s.source === "kaplan" && (s.stage === "bachelor" || (a.level === "diploma" && !!x.degree)) ? "degree" : "masters");
  // The programme fee at each university, to compare a percentage award with a fixed sum.
  const fees = new Map<string, number>();
  for (const { p, u } of x.programmes) if (p.fee?.amount) fees.set(u.name, Math.max(fees.get(u.name) ?? 0, p.fee.amount));
  const worth = (s: PlanScholarship) => {
    const z = sizeOf(s);
    if (z.full) return 1e9;
    return Math.max(z.amount ?? 0, z.percent != null ? (z.percent / 100) * (fees.get(s.university) ?? 10000) : 0);
  };

  const fmtDay = (d: string) => new Date(`${d}T00:00:00`).toLocaleDateString(locale, { day: "numeric", month: "short", year: "numeric" });
  const applyFrom = (s: PlanScholarship) => {
    // A Kaplan bachelor's award goes in with the degree application, a few months before it starts.
    if (forOf(s) === "degree") return Math.max(now, (x.degree?.start ?? now + 4) - 4);
    const own = starts.filter((p) => p.u.name === s.university).map((p) => p.t);
    return Math.max(now, (own.length ? Math.min(...own) : start) - 12);
  };
  const cards: PlanScholarshipCard[] = [];
  // Awards with no date, one window per university and application: `sch-{university}` (master's) or `sch-degree-{university}`.
  const undated = new Map<string, PlanScholarship[]>();
  const undatedId = (s: PlanScholarship) => (forOf(s) === "degree" ? `sch-degree-${s.university}` : `sch-${s.university}`);
  // The first scholarship window of each application, for "Get scholarship documents ready".
  const firstWindow: Partial<Record<"degree" | "masters", number>> = {};
  const mark = (s: PlanScholarship, m: number) => (firstWindow[forOf(s)] = Math.min(firstWindow[forOf(s)] ?? m, m));
  for (const { s: raw, merged, also } of listings) {
    // A dated award's own round is said by its date line ("Due 2 Nov 2026", "2 Nov 2026 is for January 2027 entry"): lines repeating it go.
    const s = { ...raw, title: tidyTitle(raw.title, raw.value), prepare: raw.prepare.filter((l) => !EMPTY_LINE.test(l) && !(raw.deadline && !raw.automatic && repeatsRound(l, raw))) };
    const university = school(s.university);
    const base = { ...s, school: university, worth: worth(s), for: forOf(s), merged, also, note: null as string | null, item: null as string | null };
    const value = s.value ? ` · ${s.value}` : "";
    if (s.automatic) {
      cards.push({ ...base, status: "automatic", when: t("Automatic: no form needed"), due: null, dueBasis: null });
      continue;
    }
    if (!s.deadline) {
      cards.push({ ...base, status: "undated", when: t("No date: apply with your programme"), due: null, dueBasis: null, item: undatedId(s) });
      undated.set(undatedId(s), [...(undated.get(undatedId(s)) ?? []), s]);
      continue;
    }
    // The round that matters is the one for the student's own start at that university. When the page
    // names the intake its deadline is for ("For January 2027 entry"), the deadline moves with the intake
    // (2 Nov 2026 for January 2027 is 2 Nov 2029 for January 2030); otherwise it is the same day and month
    // in the first year from 12 months before the start. A month named before the deadline is not its
    // intake ("Scholarship applications open in October 2026"), and a round never falls on or after the
    // start. A round that has passed is closed.
    const own = starts.filter((p) => p.u.name === s.university).map((p) => p.t);
    const target = s.source === "university" && own.length ? Math.min(...own) : null;
    let due = s.deadline;
    let pageIntake: number | null = null;
    if (target != null) {
      const named = intakesIn(s.intake ?? "").filter((m) => m >= monthOf(s.deadline!));
      pageIntake = named.find((m) => m % 12 === target % 12) ?? named[0] ?? null;
      if (pageIntake != null) due = addMonths(s.deadline, target - pageIntake);
      if (pageIntake == null || due >= iso(target)) {
        pageIntake = null;
        const from = target - 12;
        const m = Number(s.deadline.slice(5, 7)) - 1;
        const y = Math.floor(from / 12) + (Math.floor(from / 12) * 12 + m < from ? 1 : 0);
        due = iso(y * 12 + m, Math.min(Number(s.deadline.slice(8, 10)), lastDay(y * 12 + m)));
      }
    } else {
      // Kaplan's own awards: a stated date moves on a year at a time until it is ahead.
      for (let n = 0; due < x.today && n < 6; n++) due = `${Number(due.slice(0, 4)) + 1}${due.slice(4)}`;
    }
    const pageDate = fmtDay(s.deadline);
    if (due < x.today) {
      cards.push({
        ...base,
        status: "closed",
        when: s.deadline < x.today ? t("Last round closed {date}", { date: pageDate }) : t("{date}: for another intake", { date: pageDate }),
        due,
        dueBasis: due === s.deadline ? "official" : "typical",
      });
      continue;
    }
    const m = monthOf(due);
    mark(s, Math.max(now, m - 2));
    const id = `sch-${s.id}`;
    if (due === s.deadline) {
      cards.push({ ...base, status: "upcoming", when: t("Due {date}", { date: fmtDay(due) }), due, dueBasis: "official", item: id });
      items.push({
        id,
        lane: "scholarships",
        from: at(Math.max(now, m - 2)),
        to: due,
        title: t("Scholarship: {title}", { title: s.title }),
        short: s.title,
        detail: `${university}${value}.`,
        basis: "official",
        url: s.url,
        key: true,
        university,
        due,
        for: base.for,
      });
      continue;
    }
    // Another round's date: the round for the student's start is taken to close at the same point.
    const note =
      pageIntake != null
        ? t("{date} is for {intake} entry", { date: pageDate, intake: monthYear(locale, pageIntake, "long") })
        : s.deadline < x.today
          ? t("Last round: {date}", { date: pageDate })
          : t("{date} is for another intake", { date: pageDate });
    cards.push({ ...base, status: "last-round", when: `~${monthLabel(m)}`, due, dueBasis: "typical", note, item: id });
    items.push({
      id,
      lane: "scholarships",
      from: at(Math.max(now, m - 2)),
      to: due,
      title: t("Scholarship: {title}", { title: s.title }),
      short: s.title,
      detail: `${university}${value}. ${
        pageIntake != null
          ? t("{date} was for {intake} entry.", { date: pageDate, intake: monthYear(locale, pageIntake, "long") })
          : s.deadline < x.today
            ? t("Last round closed {date}.", { date: pageDate })
            : t("{date} is for another intake.", { date: pageDate })
      } ${t("Check the page.")}`,
      basis: "typical",
      url: s.url,
      university,
      due,
      for: base.for,
    });
  }
  for (const [id, list] of undated) {
    const from = applyFrom(list[0]);
    mark(list[0], from);
    const university = school(list[0].university);
    items.push({
      id,
      lane: "scholarships",
      from: at(from),
      to: endOf(from + 3),
      title: list.length === 1 ? t("Scholarship: {title}", { title: list[0].title }) : t("Scholarships at {university} ({n})", { university, n: list.length }),
      short: list.length === 1 ? list[0].title : t("Scholarships at {university} ({n})", { university, n: list.length }),
      detail: `${list.map((s) => `${s.title}${s.value ? ` (${s.value})` : ""}`).join("; ")}. ${t("No date given. Many close early, so apply when you apply for the programme.")}`,
      basis: "typical",
      url: list[0].url,
      links: list.length > 1 ? list.filter((s) => s.url).map((s) => ({ label: s.title, url: s.url! })) : undefined,
      university,
      for: forOf(list[0]),
    });
  }
  // One "documents" step, before the first window of the master's awards (or of the degree's, when
  // there are only those).
  const docsFor = firstWindow.masters != null ? "masters" : firstWindow.degree != null ? "degree" : null;
  if (docsFor) {
    const by = Math.max(now + 1, firstWindow[docsFor]!);
    items.push({
      id: "scholarship-documents",
      lane: "scholarships",
      from: at(by - 3),
      to: endOf(by),
      title: t("Get scholarship documents ready"),
      short: t("Get scholarship documents ready"),
      detail: t("A statement for each award (why you, and what you’ll do with it), a CV with awards and activities, transcripts and one or two references: ask referees early."),
      basis: "typical",
      url: null,
      for: docsFor,
    });
  }
  // Kaplan's award for continuing students is earned during the diploma: attendance and marks count. The
  // criteria are Kaplan's (cited in the detail); the dates are the diploma's, from the student's answer.
  if (a.level === "diploma" && x.degree && grad != null && eligible.some((s) => s.id === "kaplan-progression-scholarship") && grad >= now) {
    items.push({
      id: "kaplan-merit",
      lane: "scholarships",
      from: x.today,
      to: endOf(grad),
      title: t("Keep your diploma results up for Kaplan’s scholarship"),
      short: t("Keep your grades up for Kaplan’s scholarship"),
      detail: t("Needs 90%+ attendance in every module, every exam passed first time and an 85+ average."),
      basis: "yours",
      url: null,
      for: "degree",
    });
  }

  // Experience. Student's Pass holders at schools outside MOM's list can't work in Singapore while
  // studying: online internships, partner-university activities and remote platforms only. An
  // in-person internship is suggested to citizens and PRs, and otherwise only in a gap of 3 months
  // or more between diploma and degree, with a reminder to comply with Singapore law.
  const pass = a.status === "student-pass";
  // University activities run while the student is at that university: during the planned degree.
  const stage = x.degree ? { from: x.degree.start, to: x.degree.end } : a.level === "degree" ? { from: now, to: grad ?? now + 12 } : null;
  for (const v of x.activities.filter((v) => v.universities.length)) {
    if (!stage || !x.partner || !v.universities.includes(x.partner) || stage.to < now) continue;
    if (v.start && (monthOf(v.start) < stage.from || monthOf(v.start) > stage.to)) continue;
    // Applications closed: nothing to do any more.
    if (v.applyBy && v.applyBy < x.today) continue;
    const dated = !!(v.applyBy || v.start);
    const from = dated ? (v.applyFrom && v.applyFrom > x.today ? v.applyFrom : x.today) : at(stage.from);
    const to = dated ? (v.applyBy ?? v.end) : endOf(stage.to);
    // Undated, it runs through the degree: an estimate when the degree's dates are.
    const guessed = !dated && !!x.degree?.estimate;
    items.push({
      id: `act-${v.id}`,
      lane: "experience",
      from,
      to: to && to < from ? from : to,
      title: t(v.short),
      short: t(v.short),
      detail: v.note ? t(v.note) : v.title,
      basis: dated ? "official" : guessed ? "typical" : "yours",
      url: v.url,
      key: !!v.applyBy,
      university: school(v.universities[0]),
      due: v.applyBy ?? undefined,
    });
  }
  const platforms = (mode: "online" | "in-person") => x.activities.filter((v) => !v.universities.length && v.mode === mode);
  // Experience before applying runs to the month before applications open (3 months at least).
  const until = Math.max(now + 3, firstOpen - 1);
  const online = platforms("online");
  if (online.length) {
    items.push({
      id: "online-experience",
      lane: "experience",
      from: x.today,
      to: endOf(until),
      title: t("Online internships and job simulations"),
      short: t("Do an online internship"),
      detail: t("Build experience from anywhere before you apply."),
      basis: "typical",
      url: online[0].url,
      links: online.map((v) => (v.link ? { label: t(v.link), url: v.url } : { label: v.title, url: v.url, note: v.note ? t(v.note) : undefined })),
    });
  }
  // In person: employers hiring in the student's field (their own careers pages), then listings.
  const inPerson = (id: string, from: string, to: string, title: string, short: string, detail: string, typical: boolean, rule?: PlanRule): PlanItem => {
    const shown = x.employers.slice(0, 4);
    return {
      id,
      lane: "experience",
      from,
      to,
      title,
      short,
      detail,
      basis: typical ? "typical" : "yours",
      url: shown[0]?.url ?? platforms("in-person")[0]?.url ?? null,
      links: [
        ...shown.map((e) => ({ label: e.intern ? t("{name} (internships listed)", { name: e.name }) : t("{name} careers", { name: e.name }), url: e.url })),
        ...platforms("in-person").map((v) => ({ label: v.title, url: v.url, note: v.note ? t(v.note) : undefined })),
        { label: "LinkedIn Jobs", url: "https://www.linkedin.com/jobs/" },
      ],
      rules: rule ? [rule] : undefined,
    };
  };
  let work: Plan["work"] = null;
  if (pass && x.notExempt) {
    const quote = x.mom.quotes[0] ?? "If you are holding a Student's Pass in Singapore issued by ICA, you are only allowed to work if you meet specific requirements.";
    const detail = t("Student’s Pass: no work or in-person internship in Singapore while you study at Kaplan or another private school. Your options here are online.");
    work = { line: t("Student’s Pass: no in-person work in Singapore while you study."), detail, rule: { label: t("MOM’s rule"), quote, url: x.mom.url } };
    notes.push(`${detail} MOM: “${quote}”`);
  } else if (a.status === "other-pass") {
    const line = t("Check that your pass allows work before any internship in Singapore.");
    work = { line, detail: line, rule: null };
    notes.push(line);
  } else if (a.status === "citizen-pr") {
    items.push(inPerson("internship", x.today, endOf(until), t("In-person internship in your field"), t("Do an in-person internship"), t("Do one before you apply: it strengthens your personal statement."), true));
  }
  if (x.degree && grad != null && x.degree.start - grad >= 3 && x.degree.start - 1 >= now) {
    const n = x.degree.start - grad - 1;
    items.push(
      inPerson(
        "gap-internship",
        at(grad + 1),
        endOf(x.degree.start - 1),
        t("Gap: in-person internship"),
        t("Use your {n} free months to intern in person", { n }),
        `${t("{n} free months between diploma and degree: room for an in-person internship.", { n })} ${
          pass
            ? t("Comply with Singapore law: once your Student’s Pass ends, you need a work pass. Or intern in your home country.")
            : a.status === "citizen-pr"
              ? t("Comply with Singapore law.")
              : `${t("Comply with Singapore law.")} ${t("Check that your pass allows work.")}`
        }`,
        x.degree.estimate,
        pass ? { label: t("MOM’s rule"), quote: x.mom.quotes[2] ?? "Once your Student’s Pass expires, you need a work pass to work in Singapore.", url: x.mom.url } : undefined,
      ),
    );
  }

  // Goals the student added on Where you stand.
  for (const g of a.goals ?? []) items.push(goalItem(g, x.today, t, locale));

  // Key skills added from a hot role's gap on /careers: a Kaplan module during the degree (the degree's stop),
  // or one to close outside the courses (the gap before the master's). plan-road.ts places them by id.
  const studyEnd = x.degree && x.degree.end >= now ? endOf(x.degree.end) : grad != null && grad >= now ? endOf(grad) : null;
  for (const g of a.skillGaps ?? []) {
    const words = { role: g.role, skill: g.skill, module: g.module ?? "", level: g.level };
    if (g.via === "kaplan" && g.module) {
      const short = t("Take {module} for {skill}", words);
      const detail = `${t(g.own ? "An elective in your degree." : "A core module of another Kaplan degree.")} ${t("{role} asks for {skill} at level {level} of 6.", words)}`;
      items.push({ id: `goal-module-${g.id}`, lane: "study", from: x.today, to: studyEnd, title: `${g.role}: ${short}`, short, detail, basis: "yours", url: null });
    } else {
      const short = t("Cover {skill} outside your courses", words);
      const detail = `${t("Your degree’s modules don’t cover it: a master’s or a certificate can.")} ${t("{role} asks for {skill} at level {level} of 6.", words)}`;
      items.push({ id: `goal-skill-${g.id}`, lane: "experience", from: x.today, to: null, title: `${g.role}: ${short}`, short, detail, basis: "yours", url: null });
    }
  }

  items.sort((p, q) => p.from.localeCompare(q.from) || p.lane.localeCompare(q.lane));
  const order = { upcoming: 0, "last-round": 1, undated: 2, automatic: 3, closed: 4 };
  cards.sort((p, q) => order[p.status] - order[q.status] || (p.due ?? "").localeCompare(q.due ?? "") || p.university.localeCompare(q.university));
  return { start, end, from: now, items, notes, scholarships: cards, work, asks };
}
